#include <cstddef>
#include <iostream>
#include <memory>

class Arena
{
public:
    explicit Arena(std::size_t size) : m_buffer{new std::byte[size]}, m_size{size} {}
    void* allocate(std::size_t bytes, std::size_t align) { return nullptr; }

private:
    std::unique_ptr<std::byte[]> m_buffer;
    std::size_t m_size;
    std::size_t m_used{};
};

int main()
{
    Arena a{64};
    std::cout << a.allocate(10, 1) << '\n';
}
